#!/usr/bin/env node
// Generates the CSS custom properties and the Dart tokens from tokens/tokens.json.
// `--check` writes nothing and exits 1 when a generated file differs (run by `pnpm test` in this package).
import { readFileSync, writeFileSync, existsSync } from "node:fs"
import { dirname, resolve } from "node:path"
import { fileURLToPath } from "node:url"

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, "..")
export const OUTPUTS = {
  css: resolve(root, "src/tokens.css"),
  dart: resolve(root, "../../apps/mobile/lib/ui/tokens.g.dart"),
}
const t = JSON.parse(readFileSync(resolve(root, "tokens/tokens.json"), "utf8"))

const camel = (k) => k.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase())
const dartColor = (hex) => `Color(0xFF${hex.slice(1).toUpperCase()})`
const isHex = (v) => /^#[0-9a-f]{6}$/i.test(v)
const decl = (o, prefix = "") => Object.entries(o).filter(([k]) => !k.startsWith("$")).map(([k, v]) => `  ${prefix}${k}: ${v};`).join("\n")

export function css() {
  const theme = [
    decl(t.palette, "--color-"),
    decl(t.status, "--color-"),
    decl(t.radius && Object.fromEntries(Object.entries(t.radius).filter(([k]) => k !== "tile").map(([k, v]) => [k, `${v}px`])), "--radius-"),
    decl(t.shadow, "--shadow-"),
  ].join("\n")
  return `/* GENERATED by scripts/gen-tokens.mjs from tokens/tokens.json. Do not edit. */
@theme {
${theme}
}

:root {
${decl(t.light)}
}

/* Console light theme: only the console's <html> carries data-surface, so the customer site keeps :root. Scoped to html so
   no inner element can re-match it and undo the dark values it inherits. */
html[data-surface] {
${decl(t.console)}
}

/* Console dark theme (html[data-theme="dark"]); the customer site never sets it. Same specificity as the block above, so it wins by order. */
html[data-theme="dark"] {
  color-scheme: dark;
${decl(t.dark)}
}
`
}

export function dart() {
  const colors = (o, indent = "  ") => Object.entries(o).filter(([k, v]) => !k.startsWith("$") && isHex(v)).map(([k, v]) => `${indent}static const ${camel(k)} = ${dartColor(v)};`).join("\n")
  const radii = Object.entries(t.radius).map(([k, v]) => `  static const radius${k[0].toUpperCase()}${k.slice(1)} = ${v.toFixed(1)};`).join("\n")
  return `// GENERATED by packages/ui/scripts/gen-tokens.mjs from packages/ui/tokens/tokens.json. Do not edit.
import 'package:flutter/painting.dart';

/// Brand palette shared with the web CSS custom properties.
abstract final class BrandTokens {
${colors(t.palette)}

  // Dark ("night deck") surfaces.
${colors(t.night)}

${radii}
}
`
}

const FILES = [[OUTPUTS.css, css], [OUTPUTS.dart, dart]]
export function stale() {
  return FILES.filter(([p, f]) => !existsSync(p) || readFileSync(p, "utf8") !== f()).map(([p]) => p)
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (process.argv.includes("--check")) {
    const s = stale()
    if (s.length) { console.error(`stale generated tokens (run: pnpm --filter @unitravel/ui tokens):\n${s.join("\n")}`); process.exit(1) }
    console.log("tokens up to date")
  } else {
    for (const [p, f] of FILES) writeFileSync(p, f())
    console.log("tokens written")
  }
}
